// Already validated and projected onto this task's fields by "Normalize Input".
const variables = $input.first().json.variables;
const chunkSize = 20;

const functionLines = [
  'UnitIdentifier',
  'Definition: The variable identifies the unit (case) the data point describes.',
  'Cues: respondent id, person id, household id, enterprise id, case number, serial number.',
  '',
  'GeographicDimension',
  'Definition: The variable places the data point in a geographic area or location.',
  'Cues: country, region, NUTS code, municipality, county, postal area, place of interview.',
  '',
  'TemporalDimension',
  'Definition: The variable places the data point at a time point or period.',
  'Cues: reference year, survey round, wave, quarter, month, date of interview.',
  '',
  'Weight',
  'Definition: The variable holds a weighting factor applied when analysing the data.',
  'Cues: design weight, post-stratification weight, population size weight, analysis weight, grossing-up factor, calibration factor.',
  '',
  'SamplingDesign',
  'Definition: The variable carries the position of the unit in the sample design.',
  'Cues: primary sampling unit (PSU), stratum, cluster, sampling point, replicate.'
];

const functionContext = functionLines.join('\n');

const systemPrompt = 'You are a metadata classification assistant for DDI variableFunction.\n\nvariableFunction records an immutable characteristic of the variable itself -- what the variable IS within a dataset, not what its values say. A variable may carry several functions, and most substantive variables carry none at all.\n\nThe controlled vocabulary has exactly these five terms:\n\n' + functionContext + '\n\nFor each variable, return the list of functions that apply.\n- Use every field given for a variable together: variable_name, variable_label, variable_description, variable_source_question, variable_datatype, variable_format, variable_measure, variable_value_labels (at most the first 15 value/label pairs; variable_value_labels_total is the full count) and variable_missing_values. A missing field means it is unknown.\n- Return an empty list for any variable that simply records an observed or derived value: survey answers, measurements, counts, amounts, rates, scores, opinions, status flags, classifications of the unit such as sex, age, education or income. This is the normal case -- do not force a function.\n- Assign a function only when the variable exists to identify, position or weight the data point rather than to measure something about it.\n- UnitIdentifier is for the identifier of the unit the data point describes, not for codes that classify it: a respondent id is a UnitIdentifier, an occupation code is not.\n- Age, birth year and duration are measured values, not TemporalDimension. Use TemporalDimension only for the reference time of the data point itself.\n- Country of birth, country of citizenship and similar substantive answers are measured values, not GeographicDimension. Use GeographicDimension only when the variable places the data point in a geography.\n- Return more than one term only when the variable genuinely serves several functions.\n- Return exactly one entry per variable, echoing variable_name unchanged.';

const chunks = [];
for (let i = 0; i < variables.length; i += chunkSize) {
  chunks.push(variables.slice(i, i + chunkSize));
}

return chunks.map(chunk => ({
  json: {
    systemPrompt,
    userMessage: JSON.stringify(chunk, null, 2)
  }
}));

